#include "postquantiquecoin/storage/UtxoStorage.h"
#include "postquantiquecoin/core/Serialization.h"
#include "postquantiquecoin/storage/FileStorage.h"
namespace pqc { UtxoStorage::UtxoStorage(std::filesystem::path p):path_(std::move(p)){} Result<void> UtxoStorage::SaveSnapshot(const UTXOSet& set) const { return SaveAtomic(set); } Result<void> UtxoStorage::SaveAtomic(const UTXOSet& set) const { Serializer s; s.String("PQC_UTXO_SNAPSHOT_V1"); auto snap=set.Snapshot(); s.U64(snap.size()); for(const auto& u:snap) s.Bytes(u.Serialize()); return FileStorage::AtomicWrite(path_,s.Data()); } Result<UTXOSet> UtxoStorage::LoadSnapshot() const { UTXOSet set; if(!FileStorage::FileExists(path_)) return Result<UTXOSet>::Ok(set); auto b=FileStorage::ReadFile(path_); if(b.IsErr()) return Result<UTXOSet>::Err(b.Error()); Deserializer d(b.Value()); auto magic=d.String(); if(magic.IsErr()||magic.Value()!="PQC_UTXO_SNAPSHOT_V1") return Result<UTXOSet>::Err("bad utxo snapshot"); auto n=d.U64(); if(n.IsErr()) return Result<UTXOSet>::Err(n.Error()); std::vector<UTXO> v; for(uint64_t i=0;i<n.Value();++i){ auto ub=d.Bytes(); if(ub.IsErr()) return Result<UTXOSet>::Err(ub.Error()); auto u=UTXO::Deserialize(ub.Value()); if(u.IsErr()) return Result<UTXOSet>::Err(u.Error()); v.push_back(u.Value()); } auto r=set.LoadSnapshot(v); if(r.IsErr()) return Result<UTXOSet>::Err(r.Error()); return Result<UTXOSet>::Ok(set); } Result<void> UtxoStorage::ValidateSnapshotChecksum() const { auto c=FileStorage::ComputeFileChecksum(path_); return c.IsOk()?Result<void>::Ok():Result<void>::Err(c.Error()); } }
